import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int atCount = 0;
        String inputStr = scanner.nextLine();
        String currentStr = "";
        List<String> results = new ArrayList<>();

        if (!inputStr.isEmpty()) {
            currentStr += inputStr.charAt(0);
            results.add(currentStr);
        }

        int index = 1;
        while (index + 1 < inputStr.length()) {
            String threeChars = "";
            String twoChars = "";

            if (index + 2 < inputStr.length()) {
                threeChars = inputStr.substring(index, index + 3);
            }
            if (index + 1 < inputStr.length()) {
                twoChars = inputStr.substring(index, index + 2);
            }

            if (threeChars.equals("dot")) {
                currentStr += '.';
                for (int j = 0; j < results.size(); j++) {
                    results.set(j, results.get(j) + '.');
                }
                index += 3;
            } else if (twoChars.equals("at")) {
                atCount++;
                for (int j = 0; j < atCount - 1; j++) {
                    results.set(j, results.get(j) + "at");
                }
                for (int j = atCount - 1; j < results.size(); j++) {
                    results.set(j, results.get(j) + '@');
                }
                currentStr += inputStr.charAt(index);
                currentStr += inputStr.charAt(index + 1);
                results.add(currentStr);
                index += 2;
            } else {
                currentStr += inputStr.charAt(index);
                for (int j = 0; j < results.size(); j++) {
                    results.set(j, results.get(j) + inputStr.charAt(index));
                }
                index++;
            }
        }

        if (!inputStr.isEmpty()) {
            char lastChar = inputStr.charAt(inputStr.length() - 1);
            for (int j = 0; j < results.size(); j++) {
                results.set(j, results.get(j) + lastChar);
            }
        }

        Collections.sort(results);
        System.out.print(results.get(0));
        scanner.close();
    }
}
